mapper.select:
SELECT id, doc_id, kb_id, chunk_index, content, embedding, page_num, section_title, token_count, doc_version, created_at FROM ( SELECT kb_doc_chunk.*, ROW_NUMBER() OVER (PARTITION BY kb_doc_chunk.kb_id ORDER BY kb_doc_chunk.embedding <=> CAST(#{embedding} AS vector)) as kb_rank FROM kb_doc_chunk JOIN kb_document ON kb_doc_chunk.doc_id = kb_document.id WHERE kb_doc_chunk.kb_id IN (
#{kbId} ) AND kb_doc_chunk.doc_version = kb_document.version AND kb_document.is_deleted = FALSE) ranked WHERE kb_rank <= #{topK} ORDER BY kb_rank, embedding <=> CAST(#{embedding} AS vector)
LIMIT #{globalTopK}
